import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158561894555',sleep=ms=>new Promise(r=>setTimeout(r,ms));
const all=['accessories-gifts-collectibles','airsoft-milsim','apparel','armed-forces-gear','art','body-armor-ballistic-protection','literature','child-safety-shop','dive-scuba','firearm-accessories','first-aid-medical-ifak','flags-patriotic-decor','flashlights-lighting','footwear-gloves-eyewear','k9-dog-gear','knives-axes-cutlery','morale-patches-tactical-id','outdoor-preparedness-gear','patriotic-american-heritage','safety-rescue-climbing','sta-brite-insignia','tactical-gear','thin-line','uniforms','watches','zippos-lighters-torches','stateside-quartermaster-logo-merch','army-national-guard-series','air-national-guard-series','products-built-for-the-line-u-s-army','products-built-for-the-line-u-s-navy','products-built-for-the-line-u-s-air-force','products-built-for-the-line-u-s-marine-corps','products-built-for-the-line-u-s-coast-guard','products-built-for-the-line-u-s-space-force','rotc-series','jrotc-series','military-schools-academies','law-enforcement-corrections','firefighting-ems-search-rescue'];
const shard=Number(process.env.SHARD||0),roots=all.filter((_,i)=>i%5===shard),browser=await chromium.launch({headless:true}),context=await browser.newContext({viewport:{width:1440,height:1000}}),page=await context.newPage(),failures=[];
async function ready(){let last;for(let a=0;a<3;a++){try{await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await page.waitForSelector('#MainContent .sq-refine-v3-sidebar',{state:'visible',timeout:15000});await sleep(500);return}catch(e){last=e;if(a<2){await page.reload({waitUntil:'domcontentloaded',timeout:90000}).catch(()=>{});await sleep(1500*(a+1))}}}throw last}
for(const root of roots){try{await page.goto(`${BASE}/collections/${root}?preview_theme_id=${THEME}`,{waitUntil:'domcontentloaded',timeout:90000});await ready();const rows=await page.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group')].flatMap(d=>{const group=(d.querySelector(':scope>summary')?.textContent||'').replace(/\s+/g,' ').trim();return[...d.querySelectorAll('input[data-kind="structural"]')].map(i=>({group,label:(i.closest('label')?.querySelector('span')?.textContent||'').replace(/\s+/g,' ').trim(),target:i.dataset.target||'',checked:i.checked}))}));const bad=[];for(const r of rows){try{const u=new URL(r.target,BASE),path=u.pathname.replace(/\/$/,'');if(u.searchParams.get('sq_root')!==root)bad.push({...r,reason:'wrong sq_root'});if(path==='/collections/all')bad.push({...r,reason:'generic /collections/all target'});if(path===`/collections/${root}`&&!r.checked)bad.push({...r,reason:'self target'})}catch{bad.push({...r,reason:'invalid URL'})}}if(bad.length)failures.push({root,bad});console.log('STRUCTURAL_TARGET_ROOT '+JSON.stringify({root,count:rows.length,rows,bad}))}catch(e){failures.push({root,bad:[{reason:String(e)}]});console.log('STRUCTURAL_TARGET_ROOT '+JSON.stringify({root,error:String(e)}))}}
console.log('STRUCTURAL_TARGET_SUMMARY '+JSON.stringify({shard,roots:roots.length,failures}));await browser.close();if(failures.length)process.exit(1);
